    if any(row[1].lower() in ('rowid', '_rowid_', 'oid') for row in columns) or 'WITHOUT' in suffix.upper():
        raise RuntimeError('co0014 cannot preserve custom row identity')
    replacements, additions, constraints = {}, [], []
    if table == 'transactions':
        old = "CONSTRAINT ck_transaction_type CHECK (type IN ('journal_entry', 'invoice', 'sales_receipt'))"
        replacements[old] = old.replace("'sales_receipt')", "'sales_receipt', 'payment')")
    elif table == 'document_lines':
        matches = [part.strip() for part in parts if part.strip().startswith('CONSTRAINT ck_document_line_kind_side CHECK ')]
        old = "CONSTRAINT ck_document_line_kind_side CHECK ((kind = 'journal' AND account_id IS NOT NULL AND side IS NOT NULL AND side IN ('debit', 'credit') AND typeof(amount_minor_units) = 'integer' AND amount_minor_units > 0 AND account_snapshot IS NOT NULL AND json_valid(account_snapshot) AND json_type(account_snapshot) = 'object') OR (kind = 'sale' AND account_id IS NULL AND side IS NULL AND amount_minor_units IS NULL AND account_snapshot IS NULL AND original_minor_units IS NULL AND original_currency IS NULL AND rate_used IS NULL AND rate_source IS NULL))"
        if matches != [old]:
            raise RuntimeError('co0014 unknown document kind constraint')
        replacements[old] = old.replace("kind = 'sale'", "kind IN ('sale', 'payment')")
    else:
        if any(row[1].lower() == 'payment_component_id' for row in columns):
            raise RuntimeError('co0014 component column already exists')
        additions = ['\n payment_component_id VARCHAR(26)']
        constraints = ['\n CONSTRAINT fk_source_payment_component FOREIGN KEY(transaction_id, revision_id, document_line_id, payment_component_id) REFERENCES payment_components (transaction_id, revision_id, document_line_id, id)']
    for old, new in replacements.items():
        found = [i for i, part in enumerate(parts) if part.strip() == old]
        if len(found) != 1:
            raise RuntimeError('co0014 unknown constraint: ' + old)
        parts[found[0]] = parts[found[0]].replace(old, new, 1)
    boundary = next((i for i, part in enumerate(parts) if re.match(
        r'^(?:CONSTRAINT\s|PRIMARY\s+KEY|UNIQUE\s*\(|CHECK\s*\(|FOREIGN\s+KEY)', part.strip(), re.I)), len(parts))
    expanded = parts[:boundary] + additions + parts[boundary:] + constraints
    create = 'CREATE TABLE ' + quote('_co0014_' + table) + ' (' + ','.join(expanded) + suffix
    writable = ','.join(['rowid'] + [quote(row[1]) for row in columns if row[6] == 0])
    selected = ','.join(['rowid'] + [expr for row in columns for expr in
        (f'typeof({quote(row[1])})', f'quote({quote(row[1])})', f'CAST({quote(row[1])} AS BLOB)')])
    return create, writable, selected


